mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec2 q = abs(p.xy);
  return -(max(q.x * 0.866025 + q.y * 0.5, q.y) - 1.4);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, time * 6.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 40; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 18.0) break;
    t += d * 0.8;
  }
  vec3 pos = ro + rd * t;
  float streaks = step(0.7, sin(pos.z * 1.5 + atan(pos.y, pos.x) * 6.0));
  vec3 neon = mix(vec3(0.1, 0.9, 1.0), vec3(1.0, 0.2, 0.8), sin(pos.z * 0.2) * 0.5 + 0.5);
  vec3 col = streaks * neon * (1.2 + 0.5 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
